$required=@('schema','status','characterization_eligible','formal_authorization_eligible','product_head_sha','product_tree_sha','old_tooling_head_sha','old_tooling_tree_sha','new_tooling_parent_sha','tooling_head_sha','tooling_tree_sha','tooling_files','selftest_path','selftest_sha256','selftest_status','selftest_case_count','selftest_pass_count','authorized_characterization_probe_id','allowed_changed_paths','actual_changed_paths','frozen_characterization_v3_001','netstat_target_scope_policy','netstat_target_port_prefilter_green','netstat_non_listener_state_scope_green','netstat_global_target_parse_failure_count','new_netstat_adapter_sha256','new_listener_key_formatter_sha256','new_characterization_controller_sha256','formal_mcp_execution_count','first_jsonrpc_request_sent','m6_to_m11_execution_count','canonical_payload_sha256')
