if([string]$m.schema-cne'SpaceSyndicatePr90ListenerObserverToolingManifestV3'){$issues.Add('SCHEMA_MISMATCH')};if((Get-Pr90CanonicalSha256 $m)-cne[string]$m.canonical_payload_sha256){$issues.Add('CANONICAL_HASH_MISMATCH')}
$sidecar="$manifestFull.sha256";$manifestHash=Get-Pr90Sha256 $manifestFull;$sidecarGreen=(Test-Path -LiteralPath $sidecar)-and([IO.File]::ReadAllText($sidecar).Contains($manifestHash));if(-not$sidecarGreen){$issues.Add('MANIFEST_SIDECAR_MISMATCH')}
$head=(& git -C $root rev-parse HEAD).Trim();$tree=(& git -C $root rev-parse 'HEAD^{tree}').Trim();$parent=(& git -C $root rev-parse HEAD^).Trim();if($head-cne[string]$m.tooling_head_sha){$issues.Add('HEAD_MISMATCH')};if($tree-cne[string]$m.tooling_tree_sha){$issues.Add('TREE_MISMATCH')};if($parent-cne[string]$m.new_tooling_parent_sha-or$parent-cne[string]$m.old_tooling_head_sha){$issues.Add('PARENT_MISMATCH')};if(@(& git -C $root status --porcelain=v1 --untracked-files=all).Count-ne0){$issues.Add('WORKTREE_DIRTY')}
$fileMismatch=0;foreach($file in @($m.tooling_files)){if(-not(Test-Path -LiteralPath $file.path -PathType Leaf)-or(Get-Pr90Sha256 $file.path)-cne[string]$file.sha256-or(& git -C $root hash-object -- ([string]$file.relative_path)).Trim()-cne[string]$file.git_blob){$fileMismatch+=1}};if($fileMismatch-ne0){$issues.Add("TOOLING_FILE_MISMATCH:$fileMismatch")}
$actual=@(& git -C $root diff --name-only ([string]$m.old_tooling_head_sha) $head|ForEach-Object{$_.Trim()}|Where-Object{$_}|Sort-Object);if(($actual-join'|')-cne(@($m.actual_changed_paths|Sort-Object)-join'|')-or@($actual|Where-Object{$_-cnotin@($m.allowed_changed_paths)}).Count-ne0){$issues.Add('CHANGED_PATH_MISMATCH')}
$self=Get-Content -Raw -LiteralPath $m.selftest_path|ConvertFrom-Json -Depth 100 -DateKind String;$ids=@($self.cases|ForEach-Object{[int]$_.case_id});if((Get-Pr90Sha256 $m.selftest_path)-cne[string]$m.selftest_sha256-or[string]$self.schema-cne'SpaceSyndicatePr90ListenerObserverSelfTestV3'-or[string]$self.status-cne'PASS'-or[int]$self.case_count-lt57-or[int]$self.pass_count-ne[int]$self.case_count-or@(1..57|Where-Object{$_-notin$ids}).Count-ne0-or-not[bool]$self.controller_receipt_canonical_fix_green-or-not[bool]$self.controller_zero_one_many_cardinality_fix_green-or-not[bool]$self.netstat_target_port_prefilter_green-or-not[bool]$self.netstat_non_listener_state_scope_green){$issues.Add('SELFTEST_INVALID')};if([int]$self.listener_formatter_exception_count-ne0-or-not[bool]$self.first_nonempty_listener_fixture_green-or[int]$self.cross_source_false_parity_count-ne0-or[int]$self.cross_source_false_mismatch_count-ne0-or[int]$self.listener_source_adapter_parse_failure_count-ne0-or[int]$self.netstat_global_target_parse_failure_count-ne0){$issues.Add('SELFTEST_ZERO_GATE_FAILED')}
