if((Get-Pr90Sha256 $m.frozen_characterization_v2_001.result_path)-cne'b58a80636bb939bb793e57707040e39bd279759596d435f2cd7daa438ec7f216'-or(Get-Pr90Sha256 $m.frozen_characterization_v2_001.attestation_path)-cne'84a2ed5dc6fc588559143d96cd019879555fbc90d21d2257e8d7f349e8e59289'-or(Get-Pr90Sha256 $m.frozen_characterization_v2_001.failure_path)-cne'a3cab93b9f725010e7e59352c29b4da853f0b428d73fb53696953389d2da6685'){$issues.Add('PRIOR_CHARACTERIZATION_FROZEN_MISMATCH')}
if((Get-Pr90Sha256 $m.frozen_characterization_v3_001.result_path)-cne'9809619af94292b6dbb0c0429b8cfa4103b5c0fb57566553179a55dabbb4cdb3'-or(Get-Pr90Sha256 $m.frozen_characterization_v3_001.attestation_path)-cne'252e419edebc5d7b2baa24c6e5328317c3223ced7ebb02eea6b63ef8b52d7b88'-or(Get-Pr90Sha256 $m.frozen_characterization_v3_001.m0_receipt_path)-cne'6b2ddc06c8e930708c6e7b06a70a60a3060c28792d3b620d61e207109655d436'-or(Get-Pr90Sha256 $m.frozen_characterization_v3_001.terminal_path)-cne'a3a11d86e44553ec79ca43da63bad88b3b7439971c0e3e1a92ccd51e0dc6e10e'-or(Get-Pr90Sha256 $m.frozen_characterization_v3_001.diagnostic_path)-cne'68b5f422268c9da3bad7fb666d2f73524fe5ff6c089a728b508bbbe638924e81'-or(Get-Pr90Sha256 $m.frozen_characterization_v3_001.tooling_manifest_path)-cne'96d01aa9d5428f7e0f2c2b1c2d8bd11fa143d3baf44f065ab601a6bd01561ee0'-or(Get-Pr90Sha256 $m.frozen_characterization_v3_001.tooling_seal_path)-cne'c5390a49ae15e0744dc22348ea62a199085003c2ae81730685c549cf54c53928'){$issues.Add('V3_CHARACTERIZATION_FROZEN_MISMATCH')}
if([string]$m.netstat_target_scope_policy-cne'VALID_LOCAL_PORT_PREFILTER_BEFORE_LISTENER_STATE_VALIDATION_V1'-or-not[bool]$m.netstat_target_port_prefilter_green-or-not[bool]$m.netstat_non_listener_state_scope_green-or[int]$m.netstat_global_target_parse_failure_count-ne0){$issues.Add('NETSTAT_SCOPE_CONTRACT_MISMATCH')}
$eligible=($issues.Count-eq0);if([bool]$m.characterization_eligible-ne$true-or[string]$m.status-cne'READY_FOR_ONE_M0_M5_CHARACTERIZATION_ONLY'-or[bool]$m.formal_authorization_eligible-or[string]$m.authorized_characterization_probe_id-cne'pr90-m5-endpoint-owner-characterization-v4-001'){$issues.Add('ELIGIBILITY_SCOPE_MISMATCH')};if([bool]$m.first_jsonrpc_request_sent-or[int]$m.endpoint_application_request_count-ne0-or[int]$m.m6_to_m11_execution_count-ne0-or[int]$m.formal_mcp_execution_count-ne0-or[int]$m.authorized_run_count_consumed-ne0){$issues.Add('ZERO_EXECUTION_GATE_MISMATCH')}
$receipt=[ordered]@{schema='SpaceSyndicatePr90ListenerObserverToolingValidationV3';status=if($issues.Count-eq0){'PASS'}else{'FAIL'};validated_at_utc=[DateTimeOffset]::UtcNow.ToString('o');manifest_path=$manifestFull;manifest_sha256=Get-Pr90Sha256 $manifestFull;tooling_head_sha=$head;tooling_tree_sha=$tree;validated_file_count=@($m.tooling_files).Count;validated_case_count=[int]$self.case_count;file_mismatch_count=$fileMismatch;issue_count=$issues.Count;issues=@($issues);netstat_target_port_prefilter_green=[bool]$self.netstat_target_port_prefilter_green;netstat_non_listener_state_scope_green=[bool]$self.netstat_non_listener_state_scope_green;netstat_global_target_parse_failure_count=[int]$self.netstat_global_target_parse_failure_count;characterization_eligible=($issues.Count-eq0);formal_authorization_eligible=$false;first_jsonrpc_request_sent=$false;m6_to_m11_execution_count=0;formal_mcp_execution_count=0;authorized_run_count_consumed=0;canonical_payload_sha256=''};$receipt.canonical_payload_sha256=Get-Pr90CanonicalSha256 $receipt;Write-Pr90ImmutableJson -Path $OutputPath -Value $receipt -WriteSha256Sidecar|Out-Null;$receipt|ConvertTo-Json -Depth 100 -Compress;if($issues.Count-ne0){exit 2}
